INSERT INTO automation_hub.process (id, canonical_name, normalized_key, description, department_id, status, company_id, ams_year_id, go_live_date, in_pipeline, created_at, documentation_url) VALUES
('142', 'RPA - Sauron', 'rpa - sauron', 'Everyday the Digital Worker perform continuous health checks of the 11 most used Menarini’s applications. In case of any issues being revealed an email needs to be sent immediately to the specific persons that will proceed with further investigation of the issue or will take the corrective actions.', '43', 'In production', '5', '7', '2021-01-25', 't', '2026-08-24 12:52:57.444284+00', NULL),
('148', 'RPA - Goods Movement', 'rpa - goods movement', '7', '46', 'In production', '6', '7', '2021-09-24', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1CUCU-rjeWgqH34e0x3c6HFcYYmC7I7Zv'),
('163', 'RPA - Sconto Merce and Supero Valore Orders Submitting', 'rpa - sconto merce and supero valore orders submitting', 'Every day, DW converts approval emails into pdf files, then extracts SAP order number from the email subject and upload the relative .pdf file in SAP (transaction VA03).', '48', 'In production', '6', '7', '2023-01-26', 't', '2026-08-24 12:52:57.444284+00', NULL),
('172', 'RPA - Check POs', 'rpa - check pos', 'When a user creates a PR by retrieving the budget from Einstein, they should download all the PDFs containing the purchase request details received via email from Einstein and upload them to the P2P system. The Digital Worker automatically completes this process, retrieving the PDFs from the user''s email and attaching them to the PR, without the user having to do so.', '43', 'In production', '5', '7', '2023-11-20', 't', '2026-08-24 12:52:57.444284+00', NULL),
('173', 'RPA - Copies for BAP', 'rpa - copies for bap', 'Every day, the DW must download the list of invoices received from Archiflow and the list of purchase orders received from P2P, matching the purchase orders with their corresponding master invoices. If the purchase order requires the issuance of a BAP, the Digital Worker must send an email request to the user processing the purchase order, citing the invoice and purchase order details and codes.', '47', 'In production', '5', '7', '2023-11-22', 't', '2026-08-24 12:52:57.444284+00', NULL),
('174', 'RPA - Botman', 'rpa - botman', 'The robot activates a payment proposal both for suppliers and intercompany. Once the procedure has been started and the conditions of the proposal are confirmed, the payment can be run.', '51', 'In production', '5', '7', '2024-04-03', 't', '2026-08-24 12:52:57.444284+00', NULL),
('180', 'RPA - RABOT - Creating a regulatory objective in Veeva', 'rpa - rabot - creating a regulatory objective in veeva', 'Rabot will open the Database submission sheet considering only the tab Template New RO to collect the input data for the creation of the Regulatory Objective in Veeva and sending an error to the editor if it is empty. at the end of the process, Rabot will send a response to the editor who triggered the process and the DB Team, confirming whether it completed successfully or encountered any errors.', '54', 'In development', '5', '9', NULL, 't', '2026-08-24 12:52:57.444284+00', NULL),
('181', 'RPA - RABOT - Application of regulatory objective in Veeva', 'rpa - rabot - application of regulatory objective in veeva', 'Rabot will open the Database submission sheet considering only the tab Template New RO to collect the input data for the creation of the Regulatory Objective in Veeva and sending an error to the editor if it is empty. at the end of the process, Rabot will send a response to the editor who triggered the process and the DB Team, confirming whether it completed successfully or encountered any errors.', '54', 'In development', '5', '9', NULL, 't', '2026-08-24 12:52:57.444284+00', NULL),
('182', 'RPA - RABOT - COPY ORACLE', 'rpa - rabot - copy oracle', 'Daily, automation accesses Oracle Database, extract various data from different view and then stored them in a dedicated Excel file.', '54', 'In production', '5', '7', '2024-10-21', 't', '2026-08-24 12:52:57.444284+00', NULL),
('183', 'RPA - RABOT - COPY VEEVA', 'rpa - rabot - copy veeva', 'Daily, automations extract products data from specific emails and insert in Veeva portal in order to retrieve the associated report. Then, the information present in the Veeva report are copied in the corresponding Google Sheet.', '55', 'In production', '5', '9', '2024-12-20', 't', '2026-08-24 12:52:57.444284+00', NULL),
('184', 'RPA - Claims management', 'rpa - claims management', 'Custom web application that allows business users to insert all necessary information related to claims through a standard form and then they can track and store data.', '51', 'In production', '5', '7', '2025-01-01', 't', '2026-08-24 12:52:57.444284+00', NULL),
('189', 'RPA - Reporting products marketing discontinuation', 'rpa - reporting products marketing discontinuation', NULL, NULL, NULL, NULL, NULL, NULL, 'f', '2026-08-24 12:52:57.444284+00', NULL),
('190', 'RPA - User Creation & Deactivation', 'rpa - user creation & deactivation', 'Starting from a file of IDM downloaded weekly (?), the DW checks whether there are new users to be profiled in P2P or users to be disabled and proceed with the creation or deactivation.', '43', 'Under release', '5', '9', NULL, 't', '2026-08-24 12:52:57.444284+00', NULL),
('196', 'RPA - EDMA', 'rpa - edma', NULL, NULL, NULL, NULL, NULL, NULL, 'f', '2026-08-24 12:52:57.444284+00', NULL),
('197', 'RPA - Vat Liquidation', 'rpa - vat liquidation', 'The Digital Worker downloads SAP ECC, SAP S4 and AS400 VAT registers data of all Menarini Italian companies and perform series of controls on retrieved data, then send draft reports to business users.', '51', 'In development', '5', '9', NULL, 't', '2026-08-24 12:52:57.444284+00', NULL),
('198', 'RPA - Periodic Check', 'rpa - periodic check', NULL, NULL, NULL, NULL, NULL, NULL, 'f', '2026-08-24 12:52:57.444284+00', NULL),
('199', 'RPA - Invoice data enrichment', 'rpa - invoice data enrichment', 'The digital worker performs the enrichment of electronic invoices by reading PO field and completing missing data. Through a user interface BUs can validate data or change it.', '51', 'Requirement analysis', '5', '9', '2026-01-01', 't', '2026-08-24 12:52:57.444284+00', NULL),
('200', 'RPA - Closing Direct Pos', 'rpa - closing direct pos', 'The robot updates the orders in AS400 and SAP according to the changes performed by users in P2P.', '47', 'In production', '5', '7', '2024-01-08', 't', '2026-08-24 12:52:57.444284+00', NULL),
('201', 'RPA - Comm of Orders Blocked due to Insolvency', 'rpa - comm of orders blocked due to insolvency', 'Every day, the DW extracts from SAP list of orders and relative clients having a “Customer Credit status check” block. Then the bot accesses the AS400 and retrieves for each client the information regarding the expired and not paid invoices. Finally, it sends an email communication to the identified clients indicating the blocked order(s) and not compliant invoices.', '50', 'In production', '6', '7', '2022-11-25', 't', '2026-08-24 12:52:57.444284+00', NULL),
('202', 'RPA - Reporting pending orders and products', 'rpa - reporting pending orders and products', NULL, NULL, NULL, NULL, NULL, NULL, 'f', '2026-08-24 12:52:57.444284+00', NULL),
('203', 'RPA - Massive Copy of BI Upgrade', 'rpa - massive copy of bi upgrade', NULL, NULL, NULL, NULL, NULL, NULL, 'f', '2026-08-24 12:52:57.444284+00', NULL),
('137', 'RPA - Compilazione File Prodotti Mancanti', 'rpa - compilazione file prodotti mancanti', 'The digital worker performs a weekly extraction of missing OTC and check-up products, followed by data processing in the Access database.', '39', 'In production', '6', '7', '2020-09-04', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1IxJcU8UX4HcuXY1p0k3yZ316yB_4kpgU'),
('138', 'RPA - Inserimento Ordini Ricambi', 'rpa - inserimento ordini ricambi', 'On a daily basis, the bot extracts information related to warehouse stock load and uploads it into SAP.', '40', 'In production', '6', '7', '2020-09-04', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1LS22dn9E89gXTZt_JQKY5NaCIe90IUkX'),
('139', 'RPA - Ordini Fuori Canvass', 'rpa - ordini fuori canvass', 'The bot processes PDF files related to off-canvass orders and sends them to the appropriate directors based on geographic area and company affiliation.', '39', 'In production', '6', '7', '2020-09-11', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1-R3c9G3uYmAt7B2uM-tMe6qWPh-pIafG'),
('140', 'RPA - Inserimento ordini pharma BC', 'rpa - inserimento ordini pharma bc', 'The digital worker enters or updates pharma, OTC, API, and optical label orders in SAP for Berlin-Chemie.', '41', 'In production', '6', '7', '2020-09-24', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1fGgE-npCJGn3p41HBO5HQ_E7b47tw80Q'),
('141', 'RPA - Eraldo', 'rpa - eraldo', 'The bot access to EudraVigilance website and download ICSRs (.xml) related to Menarini’s products. After that the DW analyses ICSRs according to predefined parsing rules with the final purpose of deciding if an ICSR is related to Menarini products and/or to active ingredients used in Menarini’s products;
INSERT INTO automation_hub.process (id, canonical_name, normalized_key, description, department_id, status, company_id, ams_year_id, go_live_date, in_pipeline, created_at, documentation_url) VALUES
('169', 'RPA - Overcoming supply value', 'rpa - overcoming supply value', 'Once a month, the automation compares the invoiced quantity with the offered package quantity. If the first one is greater than the second one, the bot will send an alert email to the related customer.', '49', 'In production', '6', '7', '2023-11-02', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1OduSQr4d3Z5HRqxhdOyTbvs3VHzUOBo9'),
('170', 'RPA - Liquidation management', 'rpa - liquidation management', 'On a daily basis, the automation analyzes orders that are blocked due to lack of products by running he transaction ZSD046, in particular, it is focused on both wholesalers’ and pharmacies’ orders. After applying series of filters, the bot reject the remaining orders. In the end, a confirmation email is sent to business users attaching initial reports extracted from SAP.', '40', 'In production', '6', '7', '2023-11-08', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1plPETo8e2QKRcuBl-I_-LPhU50dPzms8'),
('171', 'RPA - Products out of order', 'rpa - products out of order', 'On a daily basis, the automation extracts from SAP the list of several types of products that have to be put out of order (transaction MB5M with 5 different variants). Afterwards, all identified materials are put out of order using the transaction MB1B.', '40', 'In production', '6', '7', '2023-11-09', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1or75EVR6aRhnFpPJ1z_k5hch2JGteA5R'),
('175', 'RPA Editing Mazinga', 'rpa editing mazinga', 'According to the codes’ list to be phased out or modified, the robot retrieves all necessary information to correctly perform the requested action in AS400 and, at the end, sends an email to the requestor.', '45', 'In production', '5', '7', '2024-04-08', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1q4hWwKCeOl7OAiBy7bg8kI17HNBk-H_j'),
('176', 'RPA - Analysis of Packaging Line Reports', 'rpa - analysis of packaging line reports', 'According to custom rules, the robot creates a structured report with machine protocols data to get better understanding of the production machines and reduce errors and defective goods.', '52', 'In production', '5', '8', '2024-04-19', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/0AJSRtLL3Jd20Uk9PVA'),
('177', 'RPA - Sending Master Data to warehouses', 'rpa - sending master data to warehouses', 'On a daily basis, an Excel file with new and/or updated records is sent to the warehouse’s supervisors.', '53', 'In production', '6', '8', '2024-07-16', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/13T6ew8ar2EEaf2l2fBvJlfy-u63p8sww'),
('178', 'RPA - Uploading invoices of Fine Foods', 'rpa - uploading invoices of fine foods', 'Every day, the automation downloads all pdf files from emails sent by Fine Foods and extract, from each file, all necessary information (e.g. invoice number, invoice date, …). All extracted data are inserted in SAP (transaction MIGO).', '41', 'In production', '6', '8', '2024-09-23', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1UArrACfEkAAjFwHoOglA09jjRUKfnPFm'),
('179', 'RPA - Replenishment of stock quantities', 'rpa - replenishment of stock quantities', 'Multiple times a day, the stock levels of all Menarini Group''s warehouses are matched with the central warehouse in Capalle using the SAP transaction ZINV001. Based on the required days of coverage it’s necessary to choose between standard or urgent STO. Results are reported to the central warehouse’s business users.', '40', 'In production', '6', '8', '2024-09-24', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1ON0VjAFcxNdEPF-mHgYFRPYUp6QqBYc7'),
('185', 'RPA - NSO Orders Check', 'rpa - nso orders check', 'Twice a day, the PDFs related to NSO orders are moved from Daphne Menarini Diagnostic server (FileZilla) to Daphne Menarini Diagnostic internal (FileZilla). Within SAP (using transaction WE02), IDOCs located in the ZNSO_orders_diagnostic folder are checked. Launching SQVI transaction, a comparison is made to ensure the documents count between SAP and FileZilla matches. An email is sent to users to inform them of the orders'' successful uploading.', '48', 'In production', '6', '9', '2025-01-27', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1jsCKPUECRWz1vI1fI9ugpU_Ec9XS5GyY'),
('186', 'RPA - Uploading invoices of LMSA Spain', 'rpa - uploading invoices of lmsa spain', 'Every day, the automation downloads all files from emails sent by LMSA and extracts all necessary information related to invoices, then checks if the processing invoice is already present in SAP with the transaction ME2N. If compared quantities are equal, all extracted data are inserted in SAP (transaction MIGO) and then the bot checka if inserted data has been correctly uploaded (transaction MMBE).', '41', 'In production', '6', '7', '2025-02-18', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1pciwZ2moZvZZIOxU3TkJN0_iKBo-TJFo'),
('187', 'RPA - Inserting pharma orders in Salesforce', 'rpa - inserting pharma orders in salesforce', 'Multiple times a day, orders from pharmacies are entered into Salesforce based on the customer code and the order type (Direct, Transfer Order, Ethical). All needed information are retrieved from PDF orders. Once filled out, orders are left in a pending state to allow reviews and potential changes', '56', 'In production', '6', '9', '2025-02-19', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1yAwixOeTVURl4W2Pz7dNN3Gr0IoBB24V'),
('188', 'RPA - Reporting Blocked Rows', 'rpa - reporting blocked rows', 'The DW extracts from SAP the list of all pending orders, pending products, pending rents, obsolete products and row blocked for price different and CIG. Each extracted information will be stored in a certain Excel file, formatted and sent to relative business users.', '48', 'In production', '6', '7', '2025-06-12', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1KghQ25YNIoopBH5znj5cFOySCMwHU0M2'),
('191', 'RPA - Doraemon', 'rpa - doraemon', 'Each month Menarini has to submit business turnover data to the European Diagnostic Manufacturers Association (EDMA) by uploading a report to the MIS Portal. The report includes the sales performance of specific products identified by a unique MIS code, incoming from all Menarini affiliates. Each affiliate sends the data using a standard template. All the data provided by the affiliates will be consolidated into a single Excel file report. Then a .csv file containing all the required sales information will be generated from the Excel report and it must be uploaded to the MIS Portal.', '57', 'In production', '5', '9', '2025-07-01', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/0ANqfbG9uvwVrUk9PVA'),
('192', 'RPA - Checking Wholesaler DDT', 'rpa - checking wholesaler ddt', 'The DW compares data extracted from BI with data from PDF orders, verifying their match to confirm payment of transfer orders to wholesalers.', '53', 'In development', '6', '9', NULL, 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/12Ltwx2S82G8w0blUCZvSRFSQYvUPBEID'),
('193', 'RPA - Replenishment UPS', 'rpa - replenishment ups', 'Menarini Group''s warehouses match their stock levels with the central warehouse in UPS multiple times a day using the SAP transaction ZINV001. The standard or urgent STO is chosen based on the required days of coverage. The delivery is then generated and sent to central warehouse’s business users via the SAP transaction VL10F.', '40', 'In production', '6', NULL, '2025-11-27', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/19wieoMtFRoTgsHtXnwGTYUPTVQLjJCvM'),
('194', 'RPA - Notifying Order Cancellation', 'rpa - notifying order cancellation', 'On a daily basis, the automation checks for blocked orders due to missing products, obsolete products or insolvency. If necessary, a cancellation letter is sent to the corresponding customer by email. Each email is then archived in SAP according to the related Sales Document', '48', 'In development', '6', NULL, NULL, 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1mefAM5OVJTCfkqyi7gwqZ_Riqpo1COUI'),
('195', 'RPA - Uploading invoices of MVH DRESDA', 'rpa - uploading invoices of mvh dresda', 'On a daily basis, the DW extracts batch information (e.g. number, expiration date, quantity, …) from MVH DRESDA invoices. Extracted data is then entered into SAP for both inbound and outbound deliveries to activate invoicing from AMFI to the Menarini Benelux affiliate.', '41', 'In production', '6', NULL, '2025-10-16', 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1v8vnLRWkEr2ukrcnn8dNwt5yxyDCgsOk'),
('204', 'RPA - Reporting products marketing discontinuation PRD', 'rpa - reporting products marketing discontinuation prd', 'The automation must send a notification email to customers when a product is no longer available on the market. For this reason, they periodically review data retrieved from BI and if necessary, they update the corresponding customers by email, sending them a defined PDF file.', NULL, NULL, NULL, NULL, NULL, 't', '2026-08-24 12:52:57.444284+00', 'https://drive.google.com/drive/u/0/folders/1cZVaY_SVqtCbp4m0F2Tb33k4BdxS3NsU');
